// tapovan_maharaj_ta.dart
// தபோவன மகாராஜ் மேற்கோள்கள் மற்றும் கட்டுரைகள்

import '../articlesquotes.dart';

final tapovanMaharajSaintTa = Saint(
  'tapovan_maharaj',
  'தபோவன மகாராஜ்',
  'assets/images/tapovan_maharaj.jpg',
  [
    'மனித வாழ்வின் உச்ச இலக்கு ஆத்ம சாக்ஷாத்காரம்; மற்ற எல்லாம் துணை மட்டுமே.',
    'தனிமை என்பது ஏகாந்தம் அல்ல; அது ஆத்மாவுடன் ஒன்றிப்படும் ஆனந்தம்.',
    'இமயமலைகள் வெறும் பனிமலைகள் அல்ல; அவை ஆன்மீக சக்தியின் வாசஸ்தலம்.',
    'உண்மையான துறவு செயலில் அல்ல; மனதில் தான்.',
    'மெய்ஞானம் பெற்ற ஆத்மாவின் மொழி மௌனம்.',
    'சாஸ்திரங்கள் வரைபடங்கள் போன்றவை; இலக்கை அடைய பாதையில் நடந்தே ஆக வேண்டும்.',
    'தியானம் என்பது மனதை கட்டிப்பிடித்தல் அல்ல; எண்ணங்கள் அடங்கும் போது தோன்றும் இயல்பான நிலை.',
    'உண்மையான குரு கற்பிப்பவர் மட்டும் அல்ல; தன் இருப்பினாலேயே மாற்றுபவர்.',
    'இயற்கையின் அழகு அனைத்திலும் உறையும் தெய்வத்தின் பிரதிபலிப்பு.',
    'வாழ்க்கையில் எளிமை சிந்தனையில் தெளிவை அளிக்கும்.',
    'பயிற்சியில்லா ஞானம் எண்ணெயில்லா விளக்கைப் போன்றது.',
    'மனம் உலகில் ஆனந்தத்தை தேடும்; உண்மையான பேரானந்தம் உள்ளேயே உள்ளது.',
    'இந்நொடியிலே வாழ்வதே நித்தியத்தில் வாழ்தல்.',
    'பற்றின்மை அலட்சியம் அல்ல; கட்டாய பற்றிலிருந்து விடுதலை.',
    'ஆத்மா எப்போதும் தூய்மை, எப்போதும் சுதந்திரம், எப்போதும் ஆனந்தம்.',
    'வார்த்தைகள் சத்தியத்தை சுட்டும்; சத்தியம் வார்த்தைகளுக்கு அப்பால்.',
    'ஆன்மீகப் பாதை சேர்த்தல் அல்ல; அகற்றலே.',
    'உண்மையான வலிமை பிறரை ஆளுவதில் அல்ல; தன்னை ஆளுவதில்.',
    'வாழ்க்கையின் நோக்கம் நீ உடல்–மனம் அல்ல; எல்லையற்ற ஆத்மா என்பதை உணர்வதே.',
    'தவம் மனத்தைத் தூய்மைப்படுத்தி உயர்தியானத்திற்கு தகுதியாக்கும்.',
    'மனத்தை வென்றவன் உலகை வென்றவன்.',
    'வேதங்கள் வெறும் நூல்கள் அல்ல; அவை எல்லையற்றதின் மூச்சே.',
    'பக்தியில்லா ஞானம் வறண்டு; ஞானமில்லா பக்தி முழுமையல்ல.',
    'பெறத் தயாரானவர்களிடம் குருவின் அருள் இயல்பாகப் பாய்கிறது.',
    'மனித சேவையே தெய்வ சேவை; ஆனால் முதலில் நீ யார் என்பதை அறி.',
    'ஞானிகள் தாமரைபோல் வாழ்வர் — உலகில் இருந்தும் அதனால் தொட்டுணரப்படாமல்.',
    'விழிப்புணர்வுடன் அணுகினால் ஒவ்வொரு அனுபவமும் ஆத்ம கண்டுபிடிப்பின் வாய்ப்பு.',
    'பிரார்த்தனை வேண்டுதல் அல்ல; மனதை தெய்வத்துடன் இசைக்கச் செய்வது.',
    'மிகப் பெரிய தீர்த்தயாத்திரை தலைமுதல் இதயம் வரை பயணம்.',
    'திருப்தியே உச்ச செல்வம்.',
    'அஹங்காரம் ஆன்மீக முன்னேற்றத்தின் மிகப் பெரிய தடையாகும்.',
    'மோட்சம் உலகிலிருந்து விடுதலை அல்ல; அறியாமையிலிருந்து விடுதலை.',
    'ஞானப் பாதை அனைத்தையும் — தன்னையும் — கேள்வி கேட்கும் துணிச்சலை நாடுகிறது.',
    'உண்மையான அமைதி வெளியில் இல்லை; ஆத்மாவிலே உள்ளது.',
    'சாஸ்திரங்கள் கூறும் அமரத்துவம் முடிவற்ற காலம் அல்ல; காலமற்ற நிலை.',
    'ஒழுங்கான வாழ்க்கை கட்டுப்பாடு அல்ல; உண்மையான சுதந்திரம்.',
    'தியானத்தில் அமைந்த மனம், எல்லையற்ற வானத்தை பிரதிபலிக்கும் அமைந்த ஏரியைப் போன்றது.',
    'ஆத்மாவை உணர, முதலில் நீ அல்லாததை அறிய வேண்டும்.',
    'உள்ளிருக்கும் ஆசானை எழுப்புவதே மிகப் பெரிய ஆசான்.',
    'ஆன்மீக சாதனை புதியதை அடைதல் அல்ல; இருப்பதை கண்டறிதல்.',
    'ஏகாந்தத்தில் ஆத்மா பேசும்; மௌனத்தில் தெய்வத்தின் குரலைக் கேட்கும்.',
    'இமயமலைகள் போதிக்கும் பாடம் — நிலைத்திரு, உயர்ந்திரு, தூய்மையாயிரு.',
    'வைராக்யம் வாழ்க்கையிலிருந்து ஓட்டம் அல்ல; அதன் உண்மை இயல்பை உணர்தல்.',
    'ஞானி எல்லா உயிர்களிலும் ஒரே ஆத்மாவை காண்கிறான்.',
    'தபஸ் அசுத்தங்களை எரித்து ஆத்மத் தங்கத்தை வெளிப்படுத்தும்.',
    'ஆத்மப் பயணம் நீளமானது; ஆனால் ஒரு அடியும் தேவையில்லை.',
    'ஞானம் சேர்க்கும் தகவல் அல்ல; உண்மையின் நேரடி தரிசனம்.',
    'உச்ச துறவு அஹங்கார துறவுதான்.',
    'ஆழ்ந்த தியானத்தின் அமைதியில் ஆத்மா தன்னை வெளிப்படுத்துகிறது.',
    'வாழ்க்கை ஒரு வரம்; வரம் அளித்தவனை உணர அதைப் பயன்படுத்து.',
    'எல்லைமீறிய உன் அழகின் ஈர்ப்பை, இந்த வாழ்விலேயே, சந்திரனைக் காணும் இன்பம்போல் அனுபவிக்கும் அருளை எனக்கு அளி, ஆண்டவா!',
    'ஆன்மீக வாழ்வின் முதல் படி — இறைவன் மட்டுமே உண்மை, அழியாதவன், ஆனந்தமயம் என்ற உறுதியான நம்பிக்கை.',
    'இறைவன் அருளால் சாதகன் பிரம்மநிஷ்டை கொண்ட குருவை அடைகிறான்; குருவருளால் ரகசியங்களை அறிந்து நடைமுறையில் கொண்டு வருகிறான்.',
    'உள்ளும் புறமும் எங்கும் இறைவனை காண்; எல்லா உயிர்களையும் தெய்வ வடிவமாக அறிந்து அன்புடன் நட.',
    'உச்ச சத்தியத்தை உணர அறிவியலைவிட நம்பிக்கையே துணை.',
    'உண்மையான ஏழை பணமற்றவன் அல்ல; இதய ஆனந்தமற்றவனே.',
    'இறைவன் அருளின்றி வாசனைகள் அழியாது; வாசனையழிவின்றி மனத் தூய்மை இல்லை; ஞானப் பெறுதலும் இல்லை.',
    'வடிவமற்ற நீர் பனியாக மாறுவது போல, பக்தர்களுக்காக இறைவன் வடிவம் எடுக்கிறான்.',
    'ஸ்ரத்தா அற்புதமானது; நீரை தீர்த்தமாக்கும்; கல்லை தெய்வமாக்கும்.',
    'இன்ப துன்பங்களில் அடிமையாவாத பக்தனுக்கு இல்லம் இமய குகையைப் போன்றதே.',
    'உண்மையான சாதகனே குரு உபதேசங்களை நடைமுறைப்படுத்தி தெய்வ குணங்களைப் பெற வேண்டும்.',
    'செயலின் மூலம் செயல் அற்ற தெய்வ அமைதியை அடைய வேண்டும் — இதுவே வேத ரகசியம்.',
    'எங்கும் இறைவன் ஒளிர்கிறான்; அஹங்காரம் கொண்டோர் அதை காணார்.',
    'மதத்தின் கோட்பாடுகளை சரியாகப் புரிந்து உண்மையுடன் நடைமுறைப்படுத்துவதே முக்கியம்.',
    'இறைவன் அடைதலே மனித வாழ்வின் இலக்கு; அதற்கு உதவுவது தர்மம்.',
    'உலகைத் துறப்பதால் அல்ல; பரமாத்ம சிந்தனையில் நிலைத்திருப்பதால் அமைதி.',
    'இறைவனின் மீது எல்லையற்ற அன்பே மோட்சத்தின் முதன்மை வழி.',
    'பக்தியால் மன மகிழ்ச்சியும் அமைதியும் வெளிப்படும்.',
    'ஞானி இந்த வாழ்விலேயே இடையறாத பிரம்மானந்தம் அனுபவிக்கிறான்.',
    'உண்மையான குரு தன்னுள் இருக்கும் ஆத்மாவே.',
    'இந்நொடியிலே வாழ்; கடந்த காலமும் எதிர்காலமும் நினையாதே.',
    'வாக்கிய ஒழுக்கம் பெரிய சாதனை; முடிந்தவரை இறைசிந்தனையே பேசு.',
    'மனச் செயல்கள் அடங்கியபின் ஒளிர்வது சத்தியம் — ஆத்மா.',
    'இன்று சிவராத்திரி; பரமசிவனின் திருவடி தியான நாள்.',
    'துயரை நீ ஏற்று; பிறருக்கு ஆனந்தம் பொழி.',
    'அமைதி, சத்தியம், அழகு, ஆனந்தம் — அனைத்தும் ஒரே தத்துவத்தின் பெயர்கள்.',
    'ஞானக் கோடரியால் சம்சாரத்தின் வேரை வெட்டு.',
    'ஆத்ம விசாரணையால் எழும் உடனடி ஆத்ம ஞானமே மோட்சத்தின் வழி.',
    'எதற்கும் பற்றுகொள்ளாதே; வருவதை வரவேற்று, போவதை விடு.',
    'உலகில் பயனற்ற புல்லோ தூசியோ இல்லை.',
    'தீயோர் நல்லோருக்கான பரீட்சை; அவர்களின் அடிகளை மலர்களாக ஏற்று உயர்ந்து செல்.',
    'இன்ப துன்பமின்றி இந்நொடியிலே வாழ்பவன் பிரம்ம ஞானி.',
    'நம்பிக்கையின் தீ எரிந்தால் கடும் குளிரும் எட்டாது.',
    'மனத்தை அமைதிப்படுத்தி பரமேஸ்வரன் நோக்கித் திருப்புவது உத்தம தரிசனம்.',
    'ஆன்மீக சிந்தனையில் ஆனந்தம் காண முயலு; மற்றவை லீலையே.',
    'உள்ளிருக்கும் ஆத்மாவை அறிவதுதான் அறியாமையையும் சம்சாரத்தையும் அழிக்கும்.',
    'மாசற்ற பக்தி வேரூன்றினால் வாழ்வின் நோக்கம் நிறைவேறும்.',
    'ஞானமே மோட்ச வழி; ஆனால் அது முழு பக்தியால் பெறப்படுகிறது.',
    'சாஸ்திரங்களின் நோக்கம் “நான்” என்ற சிந்தனையில் நம்பிக்கையை விதைப்பதே.',
    'ஆத்ம அனுபவம் அனைவருக்கும் உள்ளது; அது பிரம்மம் என்பதை மறக்கிறோம்.',
    'உபநிஷத்துகளை வாசித்து தியானி; ஆத்ம ஞானம் விளையும்.',
    'மனம் தூய்மையில்லையெனில் ஆயிரம் முறை கேட்டாலும் சத்தியம் உதிக்காது.',
    'வைராக்யமின்றி பிரம்ம ஞானம் இல்லை.',
    'அனைத்தின் உள்ஆத்மாவான அளவிடமுடியாத இறைவன் எளிதில் ஆள்கிறான்.',
    'மகாத்மாவின் ஒரு பார்வை நூல்கள் பலவற்றைவிட உயர்வு.',
    'செயலில் இருந்தும் ஆத்ம சிந்தனையில் நிலைத்தால் அதன் ஒளியுடன் ஒன்றிப்பாய்.',
    'மன அதிர்வுகளால் தோன்றும் அனைத்தும் பிரம்மமே.',
    'இந்த புனித பூமியில் பிறந்ததை நினைத்து அதன் ஆன்மீக பாரம்பரியத்தை மதியுங்கள்.',
    'விழிப்பில் உலகை பிரம்மமாக காண்; தியானத்தில் நீயே பிரம்மம் என உணர்.',
    'பொருள் செல்வம் நிலையற்றது; சத்திய ஞான செல்வம் நித்தியம்.'
  ],
    [
      Article(
          heading: 'இமயமலை முனிவர்',
          body: 'ஸ்வாமி தபோவன் மகாராஜ் 20ஆம் நூற்றாண்டின் சிறந்த வேதாந்த ஆச்சாரியர்களில் ஒருவராக விளங்கினார். அவருடைய ஆழ்ந்த ஞானம், தீவிர ஆன்மிக சாதனை மற்றும் இமயமலையின்மீது கொண்ட பேரன்பு அவரை சிறப்பித்தன. உத்தரகாசி மற்றும் கங்கோத்ரியின் புனித சிகரங்களில் அவர் நீண்டகாலம் தனிமையில் வாழ்ந்து, இமயமலை முனிவர்களின் பண்டைய மரபை உடலாகவே வெளிப்படுத்தினார்.\n\nதபோவன் மகாராஜிற்கு இமயமலை வெறும் புவியியல் அமைப்பு அல்ல; அது ஆன்மிக சக்தியின் உயிர்ப்பூண்ட வெளிப்பாடாக இருந்தது. மலைகளின் மௌனம், கேட்கத் தகுதியுடையவர்களுக்கு அளவற்ற உண்மைகளைப் பேசுகிறது என்று அவர் கூறுவார். மனித சமூகவாழ்க்கையின் சிதறல்களிலிருந்து விலகிய இமயமலையின் தூய சூழலில், அவர் தீவிர தியானமும் தவச்சாதனைகளும் செய்தார்.\n\nஉடலில் வாழ்ந்தபடியே விடுதலை பெற்ற ஜீவன்முக்தரின் இலட்சியத்தை அவரது வாழ்க்கை எடுத்துக்காட்டியது. பேரறிவை அடைந்தபோதும் அவர் பணிவுடனும் எளிமையுடனும் அனைவருக்கும் அணுகத்தக்கவராக இருந்தார். அசாதாரண அனுபவங்கள் அல்ல, சாதாரண வாழ்க்கையை அசாதாரண விழிப்புணர்வுடன் வாழ்வதே உண்மையான ஆன்மிகம் என்று அவர் போதித்தார்.\n\nஅவரது எழுத்துகள், குறிப்பாக “இமயமலையில் அலைச்சல்கள்” என்ற நூல், தெய்வத்தின்மீதும் இயற்கையில் வெளிப்படும் தெய்வீகத்தின்மீதும் ஆழ்ந்த காதல் கொண்ட ஆன்மாவை வெளிப்படுத்துகின்றன. மலைகள், நதிகள், காடுகள் குறித்து அவர் எழுதிய கவிதைமிகு வர்ணனைகள், இயற்கையே அவருக்கு கோவிலாகவும் ஒவ்வொரு தருணமும் வழிபாட்டாகவும் இருந்ததை காட்டுகின்றன.\n\nஉலகம் முழுவதிலிருந்தும் ஆன்மிக தேடுபவர்களை இமயமலை ஒரு விசேஷ ஈர்ப்பால் அழைக்கிறது என்று அவர் நம்பினார். இம்மலைகளின் பரிசுத்தமான வளிமண்டலம் ஆன்மிக சாதனைக்கும் உணர்வுக்கும் ஏற்றதாகும் என்று அவர் போதித்தார். பெரும்பாலும் இமயமலை குகைகளிலும் ஆசிரமங்களிலும் கழிந்த அவரது வாழ்க்கை இதற்கு உயிருள்ள சான்றாக இருந்தது.'
      ),
      Article(
          heading: 'துறவறத்தின் மார்க்கம்',
          body: 'தபோவன் மகாராஜ் பாரம்பரிய அர்த்தத்தில் உண்மையான சந்நியாசி; ஆத்ம சாக்ஷாத்காரத்திற்காக அனைத்தையும் துறந்தவர். ஆனால் துறவறம் குறித்த அவரது போதனை ஆழ்ந்த நுட்பத்துடன் இருந்தது. உண்மையான துறவு உடல் சார்ந்தது அல்ல; அது மனதின் துறவாகும் என்று அவர் போதித்தார்.\n\nதுறவு என்பது பொறுப்புகளிலிருந்தோ வாழ்க்கையிலிருந்தோ ஓடிப்போகுதல் அல்ல. இவ்வுலகில் நிலையான ஆனந்தத்தை எதுவும் தர முடியாது என்ற தெளிவு தான் துறவின் அடிப்படை. அந்த உணர்வு இயல்பாக பற்றின்மையை உருவாக்குகிறது. ஒருவர் உலகில் வாழ்ந்து கடமைகளை நிறைவேற்றியபோதும் உள்ளார்ந்த சுதந்திரத்தில் நிலைக்கலாம்.\n\nஅவர் வலியுறுத்தியது மிக உயர்ந்த துறவு அகங்காரத்தைத் துறப்பதே என்பதாகும். தனித்த தன்மையெனும் பொய்யுணர்வே அனைத்து பற்றுகளின் மூலமாகும். அகங்காரம் நீங்கும்போது அனைத்தும் நீங்குகிறது; செயல் தொடர்ந்தாலும் செய்பவன் என்ற உணர்வு இல்லை.\n\nதபோவன் மகாராஜ் மிகவும் எளிமையான வாழ்க்கை வாழ்ந்தார். ஒரு எளிய உடை, குறைந்த உணவு, குகை அல்லது சிறிய குடியிருப்பு—அவ்வளவே அவரது தேவைகள். வெளிப்பட்ட இந்த எளிமை, அவரது உள்ளார்ந்த நிலையினுடைய இயல்பான வெளிப்பாடு. எளிமையான வாழ்க்கை ஆன்மிக சிந்தனைக்கும் சாதனைக்கும் இடத்தை உருவாக்கும் என்று அவர் போதித்தார்.\n\nதுறவு பெரும் வலிமையும் தைரியமும் தேவைப்படுவதாகவும் அவர் கூறினார். இது பலவீனர்களுக்கான பாதை அல்ல; பாதுகாப்பை விடுவித்து அறியாததை எதிர்கொள்ளத் துணியும் வீரர்களுக்கான பாதை. ஆனால் இந்த தைரியம் மனவலிமையால் அல்ல; உலகின் நிலையற்ற தன்மையை தெளிவாகப் புரிதலால் உருவாகிறது.\n\nஅவர் வாழ்ந்து காட்டிய துறவற மார்க்கம் மறுப்பு அல்ல; ஆத்மத்தின் உண்மையை உறுதிப்படுத்தும் ஒப்புதல். இது பலவற்றிலிருந்து ஒன்றிற்கும், வரம்பிலிருந்து எல்லையற்றதிற்கும் வழிநடத்தும் பாதையாகும்.'
      ),
      Article(
          heading: 'மௌனமும் தனிமையும்',
          body: 'தபோவன் மகாராஜ் மௌன சாதனையில் புகழ்பெற்றவர். நீண்டகாலம் முழுமையான மௌனத்தில் இருந்து, அவசியமான தருணங்களில் மட்டுமே பேசுவார். இது வெளிப்பட்ட ஒழுக்கமல்ல; அவரது உள்ளார்ந்த நிலையின் இயல்பான வெளிப்பாடு.\n\nமௌனத்தில் மனம் அமைதியாகிறது; அந்த அமைதியில் ஆத்மா தன்னை வெளிப்படுத்துகிறது என்று அவர் போதித்தார். சொற்கள் மனத்தில் அலைகளை எழுப்புகின்றன; அவை ஆழத்தை மறைக்கின்றன. சொற்கள் நின்றபோது அந்த ஆழம் வெளிப்படும். மௌனம் பேச்சின்மையல்ல; அது விழிப்புணர்வின் இருப்பாகும்.\n\nஅவர் கட்டாய மௌனத்தையும் இயல்பான மௌனத்தையும் வேறுபடுத்தினார். உள்ளே சிந்தனை ஓயாதபோது பேச்சைத் தவிர்ப்பது குறைந்த பயனுடையது. உள்ளார்ந்த உரையாடலும் நிற்கும் இயல்பான மௌனமே உண்மையான தியானம். அந்த மௌனத்தில் நித்தியத்தைத் தொட முடியும்.\n\nதனிமையும் அவரது சாதனையில் முக்கிய இடம் பெற்றது. மனித தொடர்புகள் இன்றி அவர் பல ஆண்டுகள் இமயமலை குகைகளிலும் காடுகளிலும் வாழ்ந்தார். ஆனால் தனிமை என்பது ஏகாந்த வேதனை அல்ல; அது தன்னுடன் இருப்பதின் ஆனந்தம் என்று அவர் கூறினார்.\n\nதனிமையில் சாதகர் தன்னையே நேராகச் சந்திக்கிறார். வெளிப்பட்ட ஆதாரங்கள் நீங்குகின்றன. இது ஆரம்பத்தில் பயமளிக்கலாம்; ஆனால் ஆன்மிக வளர்ச்சிக்குத் தேவையானது. அங்கு சமூகப் பங்குகளையும் உறவுகளையும் கடந்த உண்மையான தன்மையை அறியலாம்.\n\nதீவிர ஆன்மிக சாதகர்களுக்கு தனிமை அவசியம் என்றும் அவர் போதித்தார். உலகில் வாழ்ந்தாலும் இடைக்கிடையே ஏகாந்தத்தில் அமருவது ஆன்மிக சக்தியை ஆழப்படுத்துகிறது.\n\nஅவரது வாழ்க்கை சமநிலையின் எடுத்துக்காட்டு—நீண்ட தனிமை தியானத்துடன் சீடர்களை வழிநடத்தியும் நூல்கள் எழுதியும் இருந்தார். தனிமை சேவையிலிருந்து ஓட்டம் அல்ல; உயர்ந்த சேவைக்கான தயாரிப்பாகும்.'
      ),
      Article(
          heading: 'குரு-சிஷ்ய உறவு',
          body: 'தபோவன் மகாராஜ் ஸ்வாமி சின்மயானந்தர் உள்ளிட்ட பல ஆன்மிக ஆசிரியர்களின் குருவாக இருந்தார். அவரது போதனை பாரம்பரிய குரு-சிஷ்ய மரபில் ஆழமாக வேரூன்றியிருந்தது.\n\nஅவர் வார்த்தைகளைக் காட்டிலும் தனது இருப்பின் மூலம் போதித்தார். சீடர்கள் பல மணி நேரம் அமைதியாக அருகில் அமர்ந்தபோதும் மாற்றத்தை உணர்ந்தனர். அவரது சன்னிதி அமைதியும் ஞானமும் பரப்பியது. குருவின் முக்கிய பணியே அவர் போதிக்கும் உண்மையின் உயிரோட்டமான எடுத்துக்காட்டாக இருப்பதே என்று அவர் நம்பினார்.\n\nஅவர் பேசும்போது குறைந்த சொற்களே பயன்படுத்தினார்; ஆனால் அவை ஆழ்ந்தவை. இயற்கை எடுத்துக்காட்டுகள் மூலம் கடின ஆன்மிக உண்மைகளை விளக்கினார். இமயமலையின் மீது கொண்ட அவரது அன்பு அவரது போதனையை உயிர்ப்பித்தது.\n\nபாரம்பரிய அர்த்தத்தில் அவர் கடுமையான குருவாக இருந்தார். முழுமையான அர்ப்பணிப்பையும் கட்டுப்பாட்டையும் அவர் எதிர்பார்த்தார். ஆனால் அது ஆதிக்கத்திற்காக அல்ல; அன்பிற்காக. ஆன்மிக மாற்றத்திற்கு ஒழுக்கம் அவசியம் என்று அவர் உணர்ந்தார்.\n\nகுரு-சிஷ்ய உறவு புனிதமானதும் தனித்துவமானதும். குரு ஆன்மிகத் தந்தை; சீடரின் ஆன்மிக வாழ்க்கையைப் பிறப்பிக்கும்வர். சீடர் நம்பிக்கை, பணிவு, விடுதலைக்கான தீவிர ஏக்கம் கொண்டு அணுக வேண்டும்.\n\nஅதே நேரத்தில் குரு இலக்கு அல்ல; இலக்கை நோக்கிச் செலுத்தும் வழி என்று அவர் கூறினார். இறுதியில் உண்மையான குரு தன்நிலை ஆத்மமே.\n\nஸ்வாமி சின்மயானந்தர் உலகம் முழுவதும் வேதாந்தத்தைப் பரப்பியது, உண்மையான குரு சீடர்களை மகான்களாக உருவாக்குவதை காட்டுகிறது.'
      ),
      Article(
          heading: 'வேதாந்தம்: ஆத்மத்தின் அறிவியல்',
          body: 'தபோவன் மகாராஜ் உபநிஷத்துகளை அடிப்படையாகக் கொண்ட வேதாந்தத்தின் மாபெரும் அறிஞர். அவரது வேதாந்த அறிவு புத்திசார்ந்தது மட்டுமல்ல; நேரடி அனுபவத்தில் பிறந்தது.\n\nவேதாந்தத்தை அவர் நம்பிக்கை முறையாக அல்ல, அறிவியலாக போதித்தார். அறிவியல் வெளி உலகத்தை ஆராய்வது போல, வேதாந்தம் உள்ளார்ந்த உலகத்தை—சுத்த சித்தத்தை—ஆராய்கிறது. அறிவியல் உண்மைகள் பரிசோதனையால் உறுதிப்படுத்தப்படுவது போல, வேதாந்த உண்மைகள் தியானமும் ஆத்ம விசாரணையும் மூலம் அனுபவிக்கப்படுகின்றன.\n\nவேதாந்தத்தின் மைய போதனை ஆத்மாவும் பரம்பொருளும் ஒன்றே என்பதே. “தத் த்வம் அசி” என்ற உபநிஷத் வாக்கியம் இதை வெளிப்படுத்துகிறது. இதை உணர்வதே முக்தி.\n\nஇந்த உணர்வு வெறும் நம்பிக்கையோ அறிவாற்றலோ அல்ல என்று அவர் வலியுறுத்தினார். புத்தியால் ஏற்றுக்கொள்ளுதல் முதல் படி; ஆனால் தியானம் மற்றும் மனனத்தின் மூலம் அது நேரடி அனுபவமாக வேண்டும்.\n\n“நான் யார்?” என்ற விசாரணையை அவர் போதித்தார். இந்த விசாரணை உடல், மனம், அகங்காரம் ஆகியவற்றின் பொய்யான அடையாளங்களை நீக்கி சுத்த சித்தத்தை வெளிப்படுத்துகிறது.\n\nவேதாந்த விசாரணைக்கு முன் சரியான வாழ்க்கை அவசியம் என்றும் அவர் கூறினார். ஒழுக்கம், சுய கட்டுப்பாடு, பக்தி—இவை மனத்தை பரிசுத்தப்படுத்தி உயர்ந்த ஞானத்திற்குத் தகுதியானதாக மாற்றுகின்றன.\n\nவேதாந்தம் உலர்ந்த தத்துவம் அல்ல; மனித வாழ்வின் அடிப்படை கேள்விகளுக்கான நடைமுறை அறிவு என்று அவர் கருதினார். “நான் யார்? ஏன் துன்பப்படுகிறேன்? நிலையான ஆனந்தம் எங்கே?” என்ற கேள்விகளுக்கு இது அனுபவ அடிப்படையிலான பதிலை வழங்குகிறது.\n\nஆத்ம சாக்ஷாத்காரம் பெற்ற அவர், வெளிப்பட்ட சூழ்நிலைகளால் பாதிக்கப்படாத அமைதி மற்றும் ஆனந்தத்தில் வாழ்ந்தார். வேதாந்தம் கோட்பாடு அல்ல; வாழ்ந்த உண்மை என்பதை அவரது வாழ்க்கை நிரூபித்தது.'
      )
    ],
);
